// Config, logging and description helpers. Everything is written inside the project folder:
// logs to scratch/logs/, status to captures/. The game folder only ever holds d3d11.dll.
#include "common.h"
#include "project_dir.h"  // generated by build.cmd: #define GOH4K_PROJECT_DIR LR"(...)"
#include <cstdarg>
#include <cstdio>
#include <set>
#include <mutex>

namespace goh4k {

Config g_cfg;
volatile LONG64 g_totalFrames = 0;

static HANDLE g_log = INVALID_HANDLE_VALUE;
static SRWLOCK g_logLock = SRWLOCK_INIT;
static std::wstring g_projectDir = GOH4K_PROJECT_DIR;
static ULONGLONG g_startTick = 0;

const std::wstring& ProjectDir() { return g_projectDir; }

std::string Fmt(const char* fmt, ...) {
    char buf[2048];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(buf, sizeof(buf), fmt, ap);
    va_end(ap);
    if (n < 0) return {};
    return std::string(buf, (size_t)n < sizeof(buf) ? (size_t)n : sizeof(buf) - 1);
}

void Log(const char* fmt, ...) {
    if (g_log == INVALID_HANDLE_VALUE) return;
    char msg[2048];
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(msg, sizeof(msg), fmt, ap);
    va_end(ap);
    if (n < 0) return;
    if (n >= (int)sizeof(msg)) n = sizeof(msg) - 1;
    ULONGLONG t = GetTickCount64() - g_startTick;
    char line[2200];
    int m = snprintf(line, sizeof(line), "[%5llu.%03llu %5lu] %.*s\r\n", t / 1000, t % 1000, GetCurrentThreadId(), n, msg);
    if (m < 0) return;
    if (m >= (int)sizeof(line)) m = sizeof(line) - 1;
    AcquireSRWLockExclusive(&g_logLock);
    DWORD written;
    WriteFile(g_log, line, (DWORD)m, &written, nullptr);
    ReleaseSRWLockExclusive(&g_logLock);
}

void LogIidOnce(const char* who, REFIID riid) {
    static std::mutex mu;
    static std::set<std::string> seen;
    std::string key = std::string(who) + " " + GuidStr(riid);
    {
        std::lock_guard<std::mutex> lock(mu);
        if (!seen.insert(key).second) return;
    }
    Log("QueryInterface passed through: %s", key.c_str());
}

void WriteTextFile(const std::wstring& path, const std::string& text) {
    HANDLE h = CreateFileW(path.c_str(), GENERIC_WRITE, FILE_SHARE_READ, nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (h == INVALID_HANDLE_VALUE) return;
    DWORD written;
    WriteFile(h, text.data(), (DWORD)text.size(), &written, nullptr);
    CloseHandle(h);
}

void Init(HMODULE self) {
    g_startTick = GetTickCount64();
    std::wstring ini = g_projectDir + L"\\config\\goh4k.ini";
    g_cfg.wrap = GetPrivateProfileIntW(L"proxy", L"Wrap", g_cfg.wrap, ini.c_str());
    g_cfg.scale = GetPrivateProfileIntW(L"proxy", L"Scale", g_cfg.scale, ini.c_str());
    g_cfg.statusMs = GetPrivateProfileIntW(L"proxy", L"StatusMs", g_cfg.statusMs, ini.c_str());

    CreateDirectoryW((g_projectDir + L"\\scratch").c_str(), nullptr);
    CreateDirectoryW((g_projectDir + L"\\scratch\\logs").c_str(), nullptr);
    CreateDirectoryW((g_projectDir + L"\\captures").c_str(), nullptr);
    SYSTEMTIME st;
    GetLocalTime(&st);
    wchar_t name[96];
    swprintf_s(name, L"\\scratch\\logs\\goh4k-%04u%02u%02u-%02u%02u%02u-%lu.log", st.wYear, st.wMonth, st.wDay, st.wHour,
               st.wMinute, st.wSecond, GetCurrentProcessId());
    g_log = CreateFileW((g_projectDir + name).c_str(), FILE_APPEND_DATA, FILE_SHARE_READ, nullptr, CREATE_ALWAYS,
                        FILE_ATTRIBUTE_NORMAL, nullptr);

    wchar_t exe[MAX_PATH] = {}, dll[MAX_PATH] = {};
    GetModuleFileNameW(nullptr, exe, MAX_PATH);
    GetModuleFileNameW(self, dll, MAX_PATH);
    Log("Goh4kMod d3d11 proxy, built %s %s", __DATE__, __TIME__);
    Log("process %lu: %ls", GetCurrentProcessId(), exe);
    Log("proxy: %ls", dll);
    Log("config %ls: Wrap=%d Scale=%d StatusMs=%d", ini.c_str(), g_cfg.wrap, g_cfg.scale, g_cfg.statusMs);
}

void Shutdown(bool processExit) {
    Log("unload (%s), %lld frames presented through the wrapper", processExit ? "process exit" : "FreeLibrary",
        (long long)g_totalFrames);
    AcquireSRWLockExclusive(&g_logLock);
    if (g_log != INVALID_HANDLE_VALUE) CloseHandle(g_log);
    g_log = INVALID_HANDLE_VALUE;
    ReleaseSRWLockExclusive(&g_logLock);
}

std::string GuidStr(REFGUID g) {
    return Fmt("{%08lx-%04x-%04x-%02x%02x-%02x%02x%02x%02x%02x%02x}", g.Data1, g.Data2, g.Data3, g.Data4[0], g.Data4[1],
               g.Data4[2], g.Data4[3], g.Data4[4], g.Data4[5], g.Data4[6], g.Data4[7]);
}

std::string ModuleNameOf(const void* addr) {
    HMODULE mod = nullptr;
    if (!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                            (LPCWSTR)addr, &mod))
        return Fmt("<unknown %p>", addr);
    wchar_t path[MAX_PATH] = {};
    GetModuleFileNameW(mod, path, MAX_PATH);
    const wchar_t* base = wcsrchr(path, L'\\');
    return Fmt("%ls", base ? base + 1 : path);
}

bool IsMainModule(const void* addr) {
    HMODULE mod = nullptr;
    if (!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                            (LPCWSTR)addr, &mod))
        return false;
    return mod == GetModuleHandleW(nullptr);
}

std::string DescribeSwapChainDesc(const DXGI_SWAP_CHAIN_DESC& d) {
    return Fmt("%ux%u fmt=%d refresh=%u/%u msaa=%ux%u usage=0x%x buffers=%u hwnd=%p windowed=%d effect=%d flags=0x%x",
               d.BufferDesc.Width, d.BufferDesc.Height, (int)d.BufferDesc.Format, d.BufferDesc.RefreshRate.Numerator,
               d.BufferDesc.RefreshRate.Denominator, d.SampleDesc.Count, d.SampleDesc.Quality, d.BufferUsage,
               d.BufferCount, d.OutputWindow, d.Windowed, (int)d.SwapEffect, d.Flags);
}

static const char* AwarenessName(DPI_AWARENESS_CONTEXT ctx) {
    if (!ctx) return "?";
    if (AreDpiAwarenessContextsEqual(ctx, DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2)) return "per-monitor-v2";
    if (AreDpiAwarenessContextsEqual(ctx, DPI_AWARENESS_CONTEXT_UNAWARE_GDISCALED)) return "unaware-gdiscaled";
    switch (GetAwarenessFromDpiAwarenessContext(ctx)) {
        case DPI_AWARENESS_UNAWARE: return "unaware";
        case DPI_AWARENESS_SYSTEM_AWARE: return "system";
        case DPI_AWARENESS_PER_MONITOR_AWARE: return "per-monitor";
        default: return "invalid";
    }
}

std::string DescribeWindow(HWND hwnd) {
    RECT cr = {}, wr = {};
    GetClientRect(hwnd, &cr);
    GetWindowRect(hwnd, &wr);
    MONITORINFO mi = {sizeof(mi)};
    GetMonitorInfoW(MonitorFromWindow(hwnd, MONITOR_DEFAULTTONEAREST), &mi);
    POINT cur = {};
    GetCursorPos(&cur);
    return Fmt("client=%ldx%ld window=(%ld,%ld)-(%ld,%ld) monitor=(%ld,%ld)-(%ld,%ld) screen_metrics=%dx%d "
               "dpi_window=%u dpi_system=%u awareness_process=%s awareness_window=%s cursor=(%ld,%ld)",
               cr.right - cr.left, cr.bottom - cr.top, wr.left, wr.top, wr.right, wr.bottom, mi.rcMonitor.left,
               mi.rcMonitor.top, mi.rcMonitor.right, mi.rcMonitor.bottom, GetSystemMetrics(SM_CXSCREEN),
               GetSystemMetrics(SM_CYSCREEN), GetDpiForWindow(hwnd), GetDpiForSystem(),
               AwarenessName(GetDpiAwarenessContextForProcess(GetCurrentProcess())),
               AwarenessName(GetWindowDpiAwarenessContext(hwnd)), cur.x, cur.y);
}

}  // namespace goh4k
